int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    if (!(cin >> n >> t)) return 0;

    // dp[pos][last][trend][peaks][valleys]
    // trend: 0 = flat(start), 1 = up, 2 = down
    static long long dp[21][5][3][11][11];
    memset(dp, 0, sizeof(dp));

    // Initialize for position 1
    for (int y = 1; y <= 4; ++y) {
        dp[1][y][0][0][0] = 1;
    }

