        for (int last = 1; last <= 4; ++last) {
            for (int trend = 0; trend < 3; ++trend) {
                for (int peaks = 0; peaks <= t; ++peaks) {
                    for (int valleys = 0; valleys <= t; ++valleys) {
                        long long cur = dp[pos][last][trend][peaks][valleys];
                        if (!cur) continue;
                        for (int ny = 1; ny <= 4; ++ny) {
                            if (ny == last) continue; // no horizontal segment
                            int ntrend;
                            if (ny > last) ntrend = 1;
                            else ntrend = 2;

                            int npeaks = peaks;
                            int nvalleys = valleys;

                            if (pos >= 2) {
                                if (trend == 1 && ntrend == 2) {
                                    // up then down -> peak at pos
                                    if (pos >= 2 && pos <= n - 1) {
                                        ++npeaks;
                                    }
                                } else if (trend == 2 && ntrend == 1) {
                                    // down then up -> valley at pos
                                    if (pos >= 2 && pos <= n - 1) {
                                        ++nvalleys;
                                    }
                                }
                            }

                            if (npeaks > t || nvalleys > t - 1) continue;

                            dp[pos + 1][ny][ntrend][npeaks][nvalleys] += cur;
                        }
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int last = 1; last <= 4; ++last) {
        for (int trend = 0; trend < 3; ++trend) {
            ans += dp[n][last][trend][t][t - 1];
        }
    }

    cout << ans << '\n';
    return 0;
}

