int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    if (!(cin >> n >> t)) return 0;

    // dp[pos][y][prevDir+1][peaks][valleys]
    // pos: 1..n, y:1..4, prevDir: -1,0,1 mapped to 0,1,2
    static long long dp[21][5][3][11][11];
    memset(dp, 0, sizeof(dp));

    // Initialize for position 1: any y in [1..4], prevDir = 0 (none), peaks=0, valleys=0
    for (int y = 1; y <= 4; ++y) {
        dp[1][y][1][0][0] = 1;
    }

    for (int pos = 1; pos < n; ++pos) {
        for (int y = 1; y <= 4; ++y) {
            for (int pd = 0; pd < 3; ++pd) {
                for (int peaks = 0; peaks <= t; ++peaks) {
                    for (int valleys = 0; valleys <= t - 1; ++valleys) {
                        long long cur = dp[pos][y][pd][peaks][valleys];
                        if (!cur) continue;

                        for (int ny = 1; ny <= 4; ++ny) {
                            if (ny == y) continue; // no horizontal segment
                            int dir = (ny > y) ? 1 : -1;
                            int nd = dir + 1;

                            int npeaks = peaks;
                            int nvalleys = valleys;

                            if (pd != 1) { // previous direction exists
                                int prevDir = pd - 1;
                                if (prevDir == 1 && dir == -1) {
                                    // peak at pos
                                    if (npeaks == t) continue;
                                    ++npeaks;
                                } else if (prevDir == -1 && dir == 1) {
                                    // valley at pos
                                    if (nvalleys == t - 1) continue;
                                    ++nvalleys;
                                }
                            }

                            dp[pos + 1][ny][nd][npeaks][nvalleys] += cur;
                        }
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int y = 1; y <= 4; ++y) {
        for (int pd = 0; pd < 3; ++pd) {
            ans += dp[n][y][pd][t][t - 1];
        }
    }

    cout << ans << '\n';
    return 0;
}

