        }
    }

    for (int pos = 2; pos < n; ++pos) {
        for (int prev = 1; prev <= 4; ++prev) {
            for (int curr = 1; curr <= 4; ++curr) {
                if (prev == curr) continue;
                for (int peaks = 0; peaks <= t; ++peaks) {
                    for (int valleys = 0; valleys <= t - 1; ++valleys) {
                        for (int trend = 0; trend < 2; ++trend) {
                            long long ways = dp[pos][prev][curr][peaks][valleys][trend];
                            if (!ways) continue;
                            for (int next = 1; next <= 4; ++next) {
                                if (next == curr) continue; // no horizontal
                                int newTrend = (next > curr) ? 1 : 0;
                                int newPeaks = peaks;
                                int newValleys = valleys;

                                if (newTrend != trend) {
                                    if (trend == 1 && newTrend == 0) {
                                        // up then down -> peak at curr
                                        newPeaks++;
                                        if (newPeaks > t) continue;
                                    } else if (trend == 0 && newTrend == 1) {
                                        // down then up -> valley at curr
                                        newValleys++;
                                        if (newValleys > t - 1) continue;
                                    }
                                }

                                dp[pos + 1][curr][next][newPeaks][newValleys][newTrend] += ways;
                            }
                        }
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int prev = 1; prev <= 4; ++prev) {
        for (int curr = 1; curr <= 4; ++curr) {
            if (prev == curr) continue;
            for (int trend = 0; trend < 2; ++trend) {
                ans += dp[n][prev][curr][t][t - 1][trend];
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

